mapper.select:
select entity_id
from kg_entity
where entity_type = #{entityType}
  and external_key = #{externalKey}

select relation_id
from kg_relation
where source_entity_id = #{sourceEntityId}
  and relation_type = #{relationType}
  and target_entity_id = #{targetEntityId}

mapper.update:
update kg_evidence
set review_status = #{reviewStatus}
where material_id = #{materialId}
  and relation_id = #{relationId}

update kg_relation r
join (
    select max(reviewed_relation_type) reviewed_type
    from kg_evidence
    where material_id = #{materialId}
      and relation_id = #{relationId}
) reviewed on reviewed.reviewed_type is not null
set r.relation_type = reviewed.reviewed_type,
    r.update_time = sysdate()
where r.relation_id = #{relationId}

update kg_evidence
set review_status = #{reviewStatus}
where material_id = #{materialId}

mapper.select:
select entity_id entityId, entity_type entityType, external_key externalKey, canonical_name canonicalName, normalized_name normalizedName, properties_json propertiesJson, review_status reviewStatus, ontology_version ontologyVersion, create_time createTime, update_time updateTime from kg_entity where entity_id in
#{entityId}
order by entity_id

select r.relation_id relationId, r.relation_type relationType, r.source_entity_id sourceEntityId, se.entity_type sourceEntityType, se.canonical_name sourceEntityName, r.target_entity_id targetEntityId, te.entity_type targetEntityType, te.canonical_name targetEntityName, r.confidence, r.valid_from validFrom, r.valid_to validTo, r.review_status reviewStatus, r.ontology_version ontologyVersion, r.source_kind sourceKind, r.properties_json propertiesJson from kg_relation r join kg_entity se on se.entity_id = r.source_entity_id join kg_entity te on te.entity_id = r.target_entity_id where r.review_status <> 'REJECTED' and (r.valid_to is null or r.valid_to > sysdate()) and exists ( select 1 from kg_evidence current_ev left join expert_material current_m on current_m.material_id = current_ev.material_id where current_ev.relation_id = r.relation_id and ( current_ev.material_id is null or ( current_m.review_status = 'APPROVED' and current_m.material_id = ( select max(latest_m.material_id) from expert_material latest_m where latest_m.user_id = current_m.user_id and latest_m.material_category = current_m.material_category and latest_m.review_status = 'APPROVED' ) ) ) ) and ( r.source_entity_id in
#{entityId}
or r.target_entity_id in
#{entityId}
) order by r.relation_id

select ev.evidence_id evidenceId, ev.evidence_key evidenceKey, ev.relation_id relationId, ev.entity_id entityId, ev.source_type sourceType, ev.source_ref sourceRef, ev.material_id materialId, ev.page_no pageNo, ev.char_start charStart, ev.char_end charEnd, ev.quote_hash quoteHash, ev.excerpt, ev.confidence, ev.extractor_version extractorVersion, ev.create_time createTime from kg_evidence ev left join expert_material m on m.material_id = ev.material_id where ev.relation_id in
#{relationId}
and ( ev.material_id is null or ( m.review_status = 'APPROVED' and m.material_id = ( select max(latest_m.material_id) from expert_material latest_m where latest_m.user_id = m.user_id and latest_m.material_category = m.material_category and latest_m.review_status = 'APPROVED' ) ) ) order by ev.relation_id, ev.evidence_id

select ev.evidence_id evidenceId, ev.evidence_key evidenceKey, ev.relation_id relationId, ev.entity_id entityId, ev.source_type sourceType, ev.source_ref sourceRef, ev.material_id materialId, ev.page_no pageNo, ev.char_start charStart, ev.char_end charEnd, ev.quote_hash quoteHash, ev.excerpt, ev.confidence, ev.extractor_version extractorVersion, ev.create_time createTime from kg_evidence ev left join expert_material m on m.material_id = ev.material_id where ev.entity_id in
#{entityId}
and ( ev.material_id is null or ( m.review_status = 'APPROVED' and m.material_id = ( select max(latest_m.material_id) from expert_material latest_m where latest_m.user_id = m.user_id and latest_m.material_category = m.material_category and latest_m.review_status = 'APPROVED' ) ) ) order by ev.entity_id, ev.evidence_id
